  const A = P(-W, 0, -D), B = P(W, 0, -D), C = P(W, 0, D), E = P(-W, 0, D), A2 = P(-W, h, -D), B2 = P(W, h, -D), C2 = P(W, h, D), E2 = P(-W, h, D);
