  const glass = {c:'#7c909a', ds:true, m:0, lk:0.15, glow:'#efe4cc', gk:0.5}, panel = {c:'#d6d4cc', ds:true, m:0, lk:0.42}, steel = {c:'#99a1a6', ds:true, m:0, lk:0.6}, roof = {c:'#8a8d90', ds:true, m:0, lk:0.2};
  const tower = {c:'#e9e6df', ds:true, m:0, lk:0.9}, dark = {c:'#3a4045', ds:true, m:0, lk:0.2}, rack = {c:'#5a4d40', ds:true, m:0, lk:0.1}, deck = {c:'#7c7f80', ds:true, m:0, lk:0.2}, conc = {c:'#bbb5a8', ds:true, m:0, lk:0.45};
