  HB.walls(B.p(panel), HB.offset(ring, -0.4), 18.0, 19.2); HB.walls(B.p(dark), HB.offset(ring, -0.05), 3.0, 6.0);
  // the waiting room's shallow vaulted roof along the harbour front, glass gable ends
