  HB.walls(P(OR2), d2, 8.0, 11.0); HB.flat(P(WH), HB.offset(d2, -0.6), 11.0);
  HB.walls(P(OR), d3, 11.0, 14.0); HB.flat(P(GR), d3, 14.0);
  for (const [R, y] of [[HB.offset(hull, 0.5), 8.0], [HB.offset(d2, -0.4), 11.0]]) for (let i = 0; i < R.length; i++){ const p = R[i], q = R[(i + 1) % R.length]; HB.seg(P(WH), [p[0], y + 1.1, p[1]], [q[0], y + 1.1, q[1]], 0.05, 3); }
