  band(deck1, 4.6, 6.6, 2.4, 1.6); band(d2, 8.9, 10.6, 2.0, 1.6); band(d3, 11.8, 13.6, 2.0, 1.6);
  // pilothouses at both ends, masts, two stacks amidships
