  return {body:mk(pos, col), win:mk(W), lights:[[hl*0.7 - 4, 21.7, 0, 1, 1, 0.95], [-(hl*0.7 - 4), 21.7, 0, 1, 1, 0.95], [0, 14.5, 9.9, 0.2, 1, 0.35], [0, 14.5, -9.9, 1, 0.15, 0.1], [hl - 1, 9, 0, 1, 0.9, 0.7], [-hl + 1, 9, 0, 1, 0.9, 0.7]]};
